import{_ as p,o as a,c as o,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const i=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/BAR-CHART.md","filePath":"manual-zh/BAR-CHART.md","lastUpdated":1785684581000}'),d={name:"manual-zh/BAR-CHART.md"};function r(t,e,n,A,_,s){return a(),o("div",null,[...e[0]||(e[0]=[c(`<h4 id="_15-4-3-条形图" tabindex="-1">15.4.3 条形图 <a class="header-anchor" href="#_15-4-3-条形图" aria-label="Permalink to &quot;15.4.3 条形图&quot;">​</a></h4><p><code>BAR</code> 子命令用于生成条形图。该子命令需要指定一个计数函数（不带参数）或带有一个变量 var1 的汇总函数（var1 置于括号中）。在汇总函数或计数函数之后，应指定关键字 <code>BY</code>，然后是一个分类变量 var2。变量 var2 的取值决定了待绘制条形的标签。可选地，可以指定第二个分类变量 var3，此时将生成簇状（分组）条形图。</p><p>有效的计数函数有：</p><p><code>COUNT</code></p><p>每个类别中各个案的加权计数。</p><p><code>PCT</code></p><p>每个类别中各个案的加权计数，以占个案总权重的百分比表示。</p><p><code>CUFREQ</code></p><p>每个类别中各个案的累积加权计数。</p><p><code>CUPCT</code></p><p>每个类别中各个案的累积加权计数，以占个案总权重的百分比表示。</p><p>汇总函数针对每个类别中所有个案的 var1 应用。被认可的汇总函数有：</p><p><code>SUM</code></p><p>总和。</p><p><code>MEAN</code></p><p>算术平均值。</p><p><code>MAXIMUM</code></p><p>最大值。</p><p><code>MINIMUM</code></p><p>最小值。</p><p>以下示例假设有一个数据集，其内容是一项调查的结果。每位受访者都填写了年收入、性别和居住城市。可以创建一个条形图来展示不同城市居民的平均收入差异，如下所示：</p><pre><code>GRAPH  /BAR  = MEAN(income) BY city.
</code></pre><p>还可以进一步扩展，以显示每个城市内不同性别之间的收入差异。</p><pre><code>GRAPH  /BAR  = MEAN(income) BY city BY sex.
</code></pre><p>也许还想知道每个城市有多少人受访。可按如下方式实现：</p><pre><code>GRAPH  /BAR  = COUNT BY city.
</code></pre><p>条形图也可以使用 <a href="./FREQUENCIES">FREQUENCIES</a> 和 <a href="./CROSSTABS">CROSSTABS</a> 命令生成。</p>`,27)])])}const l=p(d,[["render",r]]);export{i as __pageData,l as default};
